module top_module(
  input clk,
  input reset,
  output reg [3:0] counter,  // Changed from wire to reg
  output max_value
);parameter MAX_VALUE = 4'hF;

  assign max_value = (counter == MAX_VALUE) ? 1'b1 : 1'b0;

  always @(posedge clk) begin
    if (reset) begin
      counter <= 4'h0;
    end
    else begin
      counter <= counter + 1;
    end
  end

endmodule

