module fsm_calculation (
        input clk,
        input rst,
        input start,
        input complete,
        output reg out);

    parameter RESET = 0, CALCULATE = 1, DONE = 2;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (rst) state <= RESET;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            RESET: next_state = start ? CALCULATE : RESET;
            CALCULATE: next_state = complete ? DONE : CALCULATE;
            DONE: next_state = rst ? RESET : DONE;
            default: next_state = 'x;
        endcase
    end

    assign out = (state == CALCULATE) || (state == DONE);

endmodule

