module jkff (
	input clk,
	input reset,
	input j,
	input k,
	output reg q
);always @(posedge clk or posedge reset) begin
	if (reset)
		q <= 1'b0;
	else if (j && ~k)
		q <= 1'b1;
	else if (~j && k)
		q <= 1'b0;
	else if (j && k)
		q <= ~q;
end

endmodule

