Design a 4-to-1 multiplexer that selects one of four 1-bit input signals based on a 2-bit selection input. The selected input is output on the 'out' line, where 'sel' determines which input is conveyed: 'sel' = 00 outputs 'in[0]', 'sel' = 01 outputs 'in[1]', 'sel' = 10 outputs 'in[2]', and 'sel' = 11 outputs 'in[3]'.
module top_module(
    input [3:0] in,
    input [1:0] sel,
    output reg out
);

code:
module top_module(
    input [3:0] in,
    input [1:0] sel,
    output reg out
);wire sel0_inv, sel1_inv;

    assign sel0_inv = ~sel[0];
    assign sel1_inv = ~sel[1];

    always @(*) begin
        if (sel == 2'b00) begin
            out = in[0];
        end else if (sel == 2'b01) begin
            out = in[1];
        end else if (sel == 2'b10) begin
            out = in[2];
        end else begin
            out = in[3];
        end
    end

endmodule

