module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter A=2'b00, B=2'b01, C=2'b10, D=2'b11;

    always_comb begin
		case (state)
			A: next_state = in1 ? C : B;
			B: next_state = in2 ? D : C;
			C: next_state = in1 ? A : D;
			D: next_state = in2 ? B : A;
		endcase
    end

    assign out = (state == B) || (state == D);

endmodule

