module top_module(
    // inputs:
    free2,
    free3,
    tm_count,

    // outputs:
    fifowp_inc
);output [3:0] fifowp_inc;
    input free2;
    input free3;
    input [1:0] tm_count;

    reg [3:0] fifowp_inc;

    always @(*) begin
        case ({free3, tm_count})
            2'b11: fifowp_inc = 3;
            2'b10: fifowp_inc = free2 ? 2 : 1;
            2'b01: fifowp_inc = 1;
            default: fifowp_inc = 0;
        endcase
    end

endmodule

