module top_module(src_clk,
    src_in_bin,
    dest_clk,
    dest_out_bin);input src_clk;
  input [3:0]src_in_bin;
  input dest_clk;
  output reg [3:0]dest_out_bin; // Changed to reg type

  wire [3:0]async_path;
  wire [2:0]binval;
  wire [2:0]gray_enc;

  // Gray code encoder
  assign gray_enc[0] = src_in_bin[1] ^ src_in_bin[0];
  assign gray_enc[1] = src_in_bin[2] ^ src_in_bin[1];
  assign gray_enc[2] = src_in_bin[3] ^ src_in_bin[2];

  // Gray code flip-flops
  reg [3:0] gray_ff;
  always @(posedge src_clk) begin
    gray_ff <= {gray_enc[2], gray_enc[1], gray_enc[0], src_in_bin[3]};
  end

  // Gray to binary conversion
  wire [3:0] binval_internal;
  assign binval_internal[0] = gray_ff[3] ^ gray_ff[2] ^ gray_ff[1];
  assign binval_internal[1] = gray_ff[3] ^ gray_ff[2];
  assign binval_internal[2] = gray_ff[3];

  // Binary flip-flops
  always @(posedge dest_clk) begin
    dest_out_bin <= {binval_internal[2], binval_internal[1], binval_internal[0], gray_ff[3]};
  end

endmodule

