description:
Design a baud rate generator that increments a 22-bit counter on each clock cycle, producing a baud tick output signal every 27 clock cycles. This module takes an active-low reset input to initialize the counter to zero, and the output `baud_tick` transitions to high when the counter reaches 26, indicating a timing pulse suitable for asynchronous serial communication.
module top_module(
input wire clk,
input wire reset_n,
output wire baud_tick
);

code:
module top_module(
input wire clk,
input wire reset_n,
output wire baud_tick
);reg [21:0] count_reg;
    wire [21:0] count_next;

    always @(posedge clk or negedge reset_n) begin
        if(!reset_n) begin
            count_reg <= 0;
        end else begin
            count_reg <= count_next;
        end
    end

    assign count_next = ((count_reg == 26) ? 0 : count_reg + 1'b1);
    assign baud_tick = ((count_reg == 26) ? 1'b1 : 1'b0);

endmodule

