module top_module(
    input wire reset,
    input wire wr_clk,
    input wire rd_clk,
    input wire [7:0] wr_data,
    input wire wr_en,
    input wire rd_en,
    output wire [7:0] rd_data,
    output wire empty,
    output wire full
);parameter DEPTH = 16;

reg [7:0] mem [DEPTH-1:0];
reg [3:0] wr_ptr = 4'd0;
reg [3:0] rd_ptr = 4'd0;
wire [3:0] wr_ptr_next = wr_ptr + 1'b1;
wire [3:0] rd_ptr_next = rd_ptr + 1'b1;
wire [3:0] wr_ptr_inc = (wr_ptr == DEPTH-1) ? 4'd0 : wr_ptr_next;
wire [3:0] rd_ptr_inc = (rd_ptr == DEPTH-1) ? 4'd0 : rd_ptr_next;
wire [3:0] wr_ptr_dec = (wr_ptr == 4'd0) ? DEPTH-1 : wr_ptr-1;
wire [3:0] rd_ptr_dec = (rd_ptr == 4'd0) ? DEPTH-1 : rd_ptr-1;
wire [3:0] wr_ptr_inc_next = (wr_en) ? wr_ptr_inc : wr_ptr;
wire [3:0] rd_ptr_inc_next = (rd_en) ? rd_ptr_inc : rd_ptr;
wire [3:0] wr_ptr_dec_next = (rd_en && wr_ptr == rd_ptr_dec) ? wr_ptr_dec : wr_ptr;
wire [3:0] rd_ptr_dec_next = (wr_en && rd_ptr == wr_ptr_dec) ? rd_ptr_dec : rd_ptr;

assign empty = (wr_ptr == rd_ptr) && !wr_en;
assign full = (wr_ptr == rd_ptr) && wr_en;
assign rd_data = mem[rd_ptr];

always @(posedge wr_clk) begin
    if (reset) begin
        wr_ptr <= 4'd0;
    end else if (wr_en && !full) begin
        wr_ptr <= wr_ptr_inc_next;
        mem[wr_ptr] <= wr_data;
    end
end

always @(posedge rd_clk) begin
    if (reset) begin
        rd_ptr <= 4'd0;
    end else if (rd_en && !empty) begin
        rd_ptr <= rd_ptr_inc_next;
    end
end

endmodule

module top_module(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input reset_n,
    input select,
    output reg [99:0] q,
    output reg [5:0] counter_out,
    output reg [99:0] functional_out
);// Define the 100-bit rotator
    reg [99:0] rotator;
    always @ (posedge clk) begin
        if (ena[0]) begin
            rotator <= {rotator[98:0], data[0]};
        end
    end

    // Define the 64-bit Johnson counter
    reg [5:0] johnson_counter;
    always @ (posedge clk) begin
        if (ena[1]) begin
            johnson_counter <= johnson_counter ^ {johnson_counter[5], johnson_counter[4], johnson_counter[3], johnson_counter[2], johnson_counter[1], johnson_counter[0]};
        end
    end

    // Define the functional module for bitwise OR
    always @ (posedge clk) begin
        if (select) begin
            functional_out <= rotator | johnson_counter;
        end else begin
            functional_out <= rotator;
        end
    end

    // Define the output registers
    always @ (posedge clk) begin
        if (load) begin
            q <= data;
            counter_out <= 0;
        end else if (reset_n == 0) begin
            q <= 0;
            counter_out <= 0;
        end else begin
            q <= rotator;
            counter_out <= johnson_counter;
        end
    end

endmodule

