description:
Design a pulse generator that outputs a HIGH signal for a defined duration when triggered by an input signal. The module uses a clock input to create a timing control, where the output pulse width is determined by the COUNT parameter, which sets the duration to approximately 10 milliseconds when the clock frequency is 1.5 kHz. The operation consists of two states: an idle state, where the output is LOW until the input signal is asserted, and an output state, where the output remains HIGH for the duration specified by COUNT before returning to the idle state.
module top_module(
           clk,
			  signal_i,
			  signal_o
          );

code:
module top_module(
           clk,
			  signal_i,
			  signal_o
          );//////////// INPUTS & OUTPUTS ////////////	 
input clk;
input signal_i;
output signal_o;

//////////// PARAMETERS ////////////
parameter COUNT = 15; // with clk of 1.5kHz corresponds to 10ms width

parameter s_idle = 1'b0;
parameter s_out = 1'b1;


//////////// SIGNALS & REGS ////////////
reg[15:0] cnt = 0;
reg state = 0;

//////////// LOGIC ////////////
always @(posedge clk) begin
		case(state)
			s_idle:
			begin
				state <= (signal_i) ? s_out : s_idle;
				cnt  <= 16'b0;
			end
			s_out:
			begin
				state <= (cnt >= COUNT) ? s_idle : s_out;
				cnt <= cnt + 16'b1;
			end
		endcase
end

//////////// OUTPUT ASSIGNS ////////////
assign signal_o = (state == s_out);

endmodule

