module debouncer (
    input wire clk,
    input wire rstn,
    input wire noisy_in,
    input wire [3:0] stable_count,
    output reg clean_out
);

reg [3:0] shift_reg;
reg [3:0] stable_counter;

always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
        shift_reg <= 4'b0;
        stable_counter <= 4'b0;
        clean_out <= 1'b0;
    end else begin
        shift_reg <= {shift_reg[2:0], noisy_in};
        if (shift_reg == {4{noisy_in}}) begin
            if (stable_counter == stable_count) begin
                clean_out <= noisy_in;
            end else begin
                stable_counter <= stable_counter + 1'b1;
            end
        end else begin
            stable_counter <= 4'b0;
        end
    end
end

endmodule

