description:
Implement the Verilog module based on the following description.
We want to create a 4-bit comparator that:

// (1) compares two 4-bit inputs 'a' and 'b',
// (2) sets the output 'gt' high if 'a' is greater than 'b',
// (3) sets the output 'lt' high if 'a' is less than 'b',
// (4) sets the output 'eq' high if 'a' is equal to 'b'.

module top_module(
    input wire [3:0] a,
    input wire [3:0] b,
    output reg gt,
    output reg lt,
    output reg eq
);

code:
module top_module(
    input wire [3:0] a,
    input wire [3:0] b,
    output reg gt,
    output reg lt,
    output reg eq
);

    always @(*) begin
        if (a > b) begin
            gt = 1;
            lt = 0;
            eq = 0;
        end else if (a < b) begin
            gt = 0;
            lt = 1;
            eq = 0;
        end else begin
            gt = 0;
            lt = 0;
            eq = 1;
        end
    end

endmodule

