module top_module(rst, inc, dec, clk, out);input wire rst;     
input wire inc;     
input wire dec;     
output wire [2:0] out;    
input wire clk;

reg [2:0] storage;

wire [3:0] addition;

assign addition = storage + {dec,dec,1'b1};

wire carry_out = addition[3];

assign sel = (carry_out & dec) | (inc & ~carry_out);

always @(posedge clk or posedge rst)begin
  if(rst) begin
    storage <= 3'b0;
  end
  else begin
    if(sel) begin
      storage <= addition[2:0];
    end
  end
end

assign out = storage;
endmodule

